CREATE OR REPLACE FUNCTION public.fn_protect_cost_product()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.cost_product IS NULL THEN
    NEW.cost_product := OLD.cost_product;  -- NULL não apaga custo existente
  END IF;

  NEW.cost_status := CASE WHEN COALESCE(NEW.cost_product,0) > 0
                          THEN 'ok' ELSE 'missing' END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_max_created_after()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  max_date TIMESTAMPTZ;
BEGIN
  SELECT MAX(created_time) INTO max_date FROM orders_amazon;
  IF max_date IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN to_char(max_date - interval '1 day', 'YYYY-MM-DD') || 'T00:00:00Z';
END;
$function$

CREATE OR REPLACE FUNCTION public.trigger_estimate_fees()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_anon_key TEXT;
BEGIN
  -- Pega a chave da tabela de config
  SELECT value INTO v_anon_key
  FROM app_config
  WHERE key = 'supabase_anon_key';

  IF v_anon_key IS NULL THEN
    RAISE WARNING 'app_config.supabase_anon_key não configurada';
    RETURN NEW;
  END IF;

  -- Chamada assíncrona para a Edge Function (fire-and-forget)
  PERFORM net.http_post(
    url := 'https://omvtqftgbkdthgfypjlx.supabase.co/functions/v1/amazon-orders-fee-estimated',
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || v_anon_key,
      'Content-Type', 'application/json'
    ),
    body := jsonb_build_object('amazon_order_id', NEW.amazon_order_id)
  );

  RETURN NEW;
END;
$function$

